fn solve(n: i8, s: Vec<char>) -> i8 {
    // Handle the case where n is negative
    if n < 0 {
        return 0;
    }

    let mut x = 0;
    let mut y = 0;
    let mut transitions = 0;
    let mut last_region = None; // None means we are on the border

    for move_char in s.iter().take(n as usize) {
        match *move_char {
            'U' => y += 1,
            'R' => x += 1,
            _ => continue, // Ignore invalid characters
        }

        // Determine the current region
        let current_region = if x > y {
            Some('A') // Region A
        } else if y > x {
            Some('B') // Region B
        } else {
            None // On the border
        };

        // Count transitions
        if let Some(region) = current_region {
            if last_region.is_none() {
                // We are moving from the border to a region, do not count
                last_region = Some(region);
            } else if last_region != Some(region) {
                // We have transitioned to a different region
                transitions += 1;
                last_region = Some(region);
            }
        } else {
            // We are on the border, reset last_region
            last_region = None;
        }
    }

    transitions
}